using UnityEngine;using Alterverse.AI;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Visuals;using CombatFeedbackComponent=Alterverse.Combat.CombatFeedback;
namespace Alterverse.Prototype
{
public sealed class FiveVsFiveTestRoster:MonoBehaviour
{
private static readonly float[] Lanes={16f,0f,-16f,16f};private static readonly HeroId[] Pool={HeroId.Veyr,HeroId.Kaelon,HeroId.Nyra,HeroId.Elyra,HeroId.Mira,HeroId.Rook};private static readonly HeroId[] LumenHeroes={HeroId.Veyr,HeroId.Kaelon,HeroId.Nyra,HeroId.Elyra,HeroId.Rook};
private void Start(){GameObject player=GameObject.Find("AV_Player");if(player==null||GameObject.Find("AV_Lumen_Kaelon")!=null)return;HeroId selected=PlayerHeroSelection.Selected;TeamMember playerTeam=player.GetComponent<TeamMember>()??player.AddComponent<TeamMember>();playerTeam.Initialize(0);HeroIdentity identity=player.GetComponent<HeroIdentity>()??player.AddComponent<HeroIdentity>();identity.Configure(selected);HeroCombatProfile profile=player.GetComponent<HeroCombatProfile>()??player.AddComponent<HeroCombatProfile>();profile.Configure(selected);HeroAbilityKit kit=player.GetComponent<HeroAbilityKit>()??player.AddComponent<HeroAbilityKit>();kit.Configure(selected);Health health=player.GetComponent<Health>();if(health!=null)health.Configure(profile.Health);if(player.GetComponent<StylizedHeroVisual>()==null)player.AddComponent<StylizedHeroVisual>();HeroId[] allies=BuildAllies(selected);for(int i=0;i<4;i++)CreateHero(allies[i],0,Lanes[i],new Vector3(-31,1,Lanes[i]),i);for(int i=0;i<5;i++){float lane=i<4?Lanes[i]:-16;CreateHero(LumenHeroes[i],1,lane,new Vector3(31,1,lane),i+1);}}
private static HeroId[] BuildAllies(HeroId selected){HeroId[] result=new HeroId[4];int index=0;for(int i=0;i<Pool.Length&&index<4;i++){if(Pool[i]==selected)continue;result[index++]=Pool[i];}return result;}
private static void CreateHero(HeroId hero,int team,float laneZ,Vector3 spawn,int styleIndex){GameObject bot=GameObject.CreatePrimitive(PrimitiveType.Capsule);bot.name=$"AV_{(team==0?"Zero":"Lumen")}_{hero}";bot.transform.position=spawn;Renderer renderer=bot.GetComponent<Renderer>();if(renderer!=null)renderer.material.color=HeroColor(hero,team);HeroIdentity identity=bot.AddComponent<HeroIdentity>();identity.Configure(hero);HeroCombatProfile profile=bot.AddComponent<HeroCombatProfile>();profile.Configure(hero);HeroAbilityKit kit=bot.AddComponent<HeroAbilityKit>();kit.Configure(hero);Health health=bot.AddComponent<Health>();health.Configure(profile.Health);TeamMember member=bot.AddComponent<TeamMember>();member.Initialize(team);bot.AddComponent<StylizedHeroVisual>();BotPersonality personality=bot.AddComponent<BotPersonality>();personality.Configure((BotPersonality.Style)(styleIndex%5));bot.AddComponent<BotTargetSensor>();MobaBotBrain brain=bot.AddComponent<MobaBotBrain>();brain.Initialize(team,laneZ,personality.Aggression,personality.Caution);brain.RefreshPersonality();BotLanePlan lanePlan=bot.AddComponent<BotLanePlan>();lanePlan.Initialize(team,laneZ);bot.AddComponent<MobaBotMover>();bot.AddComponent<MobaBotCombat>();bot.AddComponent<HeroBotAbilities>();bot.AddComponent<MobaBotRespawn>();bot.AddComponent<CombatFeedbackComponent>();}
private static Color HeroColor(HeroId hero,int team){Color c=StylizedArtDirection.HeroAccent(hero);return team==0?Color.Lerp(c,StylizedArtDirection.ZeroDark,.42f):Color.Lerp(c,StylizedArtDirection.LumenMid,.35f);}
}
}
